import { useState, useEffect } from 'react';
import axios from 'axios';

const RegistrationForm = () => {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  // Динамическая установка CSRF-токена
  useEffect(() => {
    const csrfTokenElement = document.querySelector('meta[name="csrf-token"]');
    if (csrfTokenElement) {
      const csrfToken = csrfTokenElement.getAttribute('content');
      console.log('CSRFTOKEN:', csrfToken); // Выведи токен в консоль
      axios.defaults.headers.common['X-CSRF-TOKEN'] = csrfToken;
    }
  }, []);

  const handleSubmit = async event => {
    event.preventDefault();

    try {
      const response = await axios.post('http://127.0.0.1:8000/register', {
        name,
        email,
        password,
      });

      if (response.data.success === true) {
        alert('Регистрация прошла успешно!');
      } else {
        alert(response.data.message || 'Возникла проблема при регистрации.');
      }
    } catch (error) {
      let message = '';
      if (error.response && error.response.data) {
        message = error.response.data.message || 'Ошибка регистрации';
      } else {
        message =
          'Что-то пошло не так при попытке зарегистрироваться. Проверьте подключение к Интернету.';
      }
      alert(message);
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <input
        placeholder='Имя'
        value={name}
        onChange={e => setName(e.target.value)}
      />
      <br />
      <input
        placeholder='Email'
        value={email}
        onChange={e => setEmail(e.target.value)}
      />
      <br />
      <input
        type='password'
        placeholder='Пароль'
        value={password}
        onChange={e => setPassword(e.target.value)}
      />
      <br />
      <button type='submit'>Зарегистрироваться</button>
    </form>
  );
  useEffect(() => {
    const csrfTokenElement = document.querySelector('meta[name="csrf-token"]');
    if (csrfTokenElement) {
      const csrfToken = csrfTokenElement.getAttribute('content');
      console.log('CSRFTOKEN:', csrfToken); // Выведи токен в консоль
      axios.defaults.headers.common['X-CSRF-TOKEN'] = csrfToken;
    }
  }, []);
};

export default RegistrationForm;
